<script module lang="ts">
/**
 * A scatter chart for correlation between two measures (`design/components/scatter-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/scatter-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  joinSlot,
  measureBox,
  nearest2D,
  readChartCap,
  readChartPosition,
  readingRest,
  readingView,
  scatterChartModel,
  scatterChartReadout,
  scatterChartSelection,
  toggleChartSeries,
  toggleSeries,
  watchEffect,
  type ChartAnnotation,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
  type ScatterBubble,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/charts/scatter-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'

export interface ScatterChartProps {
  /**
   * Annotations from the tier's closed union (line, band and point), all allowed on this member.
   */
  annotations?: readonly ChartAnnotation[]
  bubble?: ScatterBubble
  /**
   * One row per observation. A `null` x, y or bubble value renders **no mark** for that row and
   * series (shown as — in the twin), never a zero.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * The accessible name.
   */
  label: string
  /**
   * Shows the previous frame at reduced opacity during a refetch.
   */
  loading?: boolean
  /**
   * The locale for `Intl` formatting.
   */
  locale?: string
  /**
   * The chart tier's string catalog (`ChartMessages`). Defaults to generic English; a localized
   * host passes the same object to every chart.
   */
  messages?: ChartMessages
  /**
   * Called with the row index, series key and row at the reading position, on Enter, Space or
   * click.
   */
  onSelect?: (selection: {
    index: number
    key: string
    datum: Readonly<Record<string, string | number | null>>
  }) => void
  /**
   * The series, **at most the palette's cap**. The member reads `--pm-chart-cap` (emitted by the
   * theme at the minimum across modes) and dev-warns above it.
   */
  series: readonly ChartSeries[]
  size?: 'sm' | 'md' | 'lg'
  /**
   * The per-mark readout (no crosshair): the x, y and bubble values, each in its own format.
   */
  tooltip?: false | ChartTooltipConfig
  /**
   * The x axis, `linear` or `time`. An omitted `scale` defaults to `'linear'` here, not
   * `'band'`, because a scatter's x is a measure. `band` raises a dev warning naming BarChart,
   * and the axis renders linear.
   */
  x: ChartXAxis
  /**
   * The y axis. `domain` defaults to `'auto'` to fit the data; `'zero'` anchors at zero.
   */
  y?: ChartYAxis
}
</script>

<script lang="ts">
let {
  annotations,
  bubble,
  data,
  label: labelOwn,
  loading = false,
  locale,
  messages = (() => DEFAULT_CHART_MESSAGES)(),
  onSelect,
  series,
  size = 'md',
  tooltip = (() => ({}))(),
  x,
  y,
}: ScatterChartProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get select() {
    return onSelect !== undefined
  },
}
let box = $state(UNMEASURED)
let reading = $state(createReading({ count: 0, seriesStart: 0 }))
let position = $state(readingRest(0))
let hidden = $state(new Set<string>())
let twinOpen = $state(false)
let warningLog = $state(createWarningLog())
let cap = $state(readChartCap(null))
let frame = $state<HTMLElement | null>(null)
let plot = $state<HTMLElement | null>(null)
const input = $derived({
  data,
  series,
  x,
  y,
  bubble,
  annotations,
  label,
  locale,
  messages,
  tooltip,
  loading,
  selectable: listening.select,
  hidden,
  cap,
  box,
})
const model = $derived(scatterChartModel(input))
const view = $derived(readingView(position, data.length, model.visible.length))
const readout = $derived(scatterChartReadout(input, model, view))
const walked = $derived(view.series ?? 0)
const activate = $derived(() => {
  const selection = scatterChartSelection(input, model, reading.now())
  if (selection !== null) onSelect?.(selection)
})
const walk = $derived({
  count: data.length,
  seriesCount: model.visible.length,
  walkSeries: true,
  seriesStart: 0,
})
const marks = $derived({
  walk,
  input,
  model,
  readout: scatterChartReadout,
  selection: scatterChartSelection,
})
const onKey = $derived((event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate()
    return
  }
  reading.update(walk)
  if (reading.key(event.key)) event.preventDefault()
})
const onPointer = $derived((event: PointerEvent) => {
  if (model.plot === null) return
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  const hit = nearest2D(model.points, event.clientX - rect.left, event.clientY - rect.top)
  if (hit === -1) {
    reading.clear()
    return
  }
  reading.moveTo(hit % data.length, Math.floor(hit / data.length))
})
const effect1 = () => {
  cap = model.state === 'empty' ? cap : readChartCap(plot)
}
watchEffect(effect1, { watch: () => model.state === 'empty' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const run = () => {
    box = plot === null ? box : measureBox(plot, box)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot]) if (element) resize?.observe(element)
  release2 = () => {
    resize?.disconnect()
  }
  run()
}
watchEffect(effect2)
onDestroy(() => release2?.())
const effect3 = () => {
  reading.subscribe((now) => {
    position = now
  })
}
watchEffect(effect3)
const effect4 = () => {
  warningLog.log(model.warnings, (message) => devWarning(true, message))
}
watchEffect(effect4, { watch: () => model.warnings.join('\n') })
let release5: (() => void) | undefined
const effect5 = () => {
  release5?.()
  const ran =
    !listening.select && !model.legend
      ? () => {}
      : agentMember({
          member: 'ScatterChart',
          element: () => frame,
          state: () => ({
            items: listening.select ? chartMarks(marks, reading) : [],
            position: chartPosition(marks, reading),
            count: walk.count,
            series: chartSeries(frame, chartLegend.key, model.painted),
            hidden: chartHiddenSeries(frame, chartLegend.key, model.painted),
          }),
          actions: {
            read: { argument: 'number', run: (value) => readChartPosition(marks, value, reading) },
            choose: {
              argument: 'id',
              among: 'items',
              run: (value) => chooseChartMark(marks, value, reading, activate),
            },
            toggle: {
              argument: 'id',
              among: 'series',
              run: (value) => toggleChartSeries(frame, chartLegend.key, model.painted, value),
            },
          },
        })
  release5 = () => {
    ran()
  }
}
watchEffect(effect5)
onDestroy(() => release5?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<figure
    bind:this={frame}
    class={chartFrame.frame}
    data-size={size}
    data-state={model.state}
    data-position={view.active ? view.index : undefined}
    aria-label={label}
    data-member="scatter-chart"
    ><div class={chartFrame.region}
      ><div class={chartFrame.yAxis}
        >{#if (model.axes?.y) !== undefined
          }<div class={chartAxis.axis} data-orientation="y" aria-hidden="true"
            >{#each (model.axes?.y) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:top={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
      ><div bind:this={plot} class={chartFrame.plot}
        >{#if model.state === 'empty'
          }<div class={chartFrame.empty}><span>{messages.empty}</span></div
        >{:else
          }<div
            class={styles.surface}
            tabindex="0"
            role="img"
            aria-label={label}
            onkeydown={(event) => { onKey(event) }}
            onclick={() => { activate() }}
            onpointermove={(event) => { onPointer(event) }}
            onpointerleave={() => { reading.clear() }}
            onblur={() => { reading.clear() }}
            >{#if model.plot !== null
              }<svg
                class={styles.marks}
                data-reading={(view.active) ? '' : undefined}
                width={model.plot?.width}
                height={model.plot?.height}
                aria-hidden="true"
                focusable="false"
                ><g class={styles.grid}
                  >{#each model.plot?.grid ?? [] as line (line.key)}<path d={line.d}></path>{/each
                }</g
                >{#each model.plot?.zero ?? [] as rule (rule.key)
                  }<path class={styles.zero} d={rule.d}></path
                >{/each
                }{#if (model.plot?.wash ?? []).length > 0
                  }<g class={chartNotes.washes}
                    >{#each (model.plot?.wash ?? []) as span (span.key)
                      }<rect
                        class={chartNotes.span}
                        x={span.x}
                        y={span.y}
                        width={span.width}
                        height={span.height}
                      ></rect
                    >{/each
                  }</g
                >{/if
                }<g class={styles.points}
                  >{#each model.plot?.groups ?? [] as group (group.key)
                    }<g
                      style:--pm-chart-mark={group.paint}
                      data-active={(view.active && walked === group.series) ? '' : undefined}
                      >{#each group.dots as dot (dot.index)
                        }<circle
                          class={styles.dot}
                          style:--pm-chart-dot={dot.index}
                          cx={dot.cx}
                          cy={dot.cy}
                          r={dot.r}
                          data-active={(view.index === dot.index && walked === group.series) ? '' : undefined}
                        ></circle
                      >{/each
                    }</g
                  >{/each
                }</g
                >{#if (model.plot?.ink ?? null) !== null
                  }<g class={chartNotes.ink}
                    >{#each (model.plot?.ink ?? null)?.spans ?? [] as span (span.key)
                      }<g
                        ><path class={chartNotes.edge} d={span.from}></path
                        ><path class={chartNotes.edge} d={span.to}></path
                      ></g
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.rules ?? [] as rule (rule.key)
                      }<path class={chartNotes.rule} d={rule.d}></path
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.marks ?? [] as mark (mark.key)
                      }<circle class={chartNotes.mark} cx={mark.cx} cy={mark.cy} r={mark.r}></circle
                    >{/each
                    }{#each (model.plot?.ink ?? null)?.labels ?? [] as note (note.key)
                      }<text
                        class={chartNotes.label}
                        x={note.x}
                        y={note.y}
                        text-anchor={note.anchor}
                        >{note.text
                      }</text
                    >{/each
                  }</g
                >{/if
              }</svg
            >{/if
          }</div
        >{/if
        }{#if readout.tooltip !== null
          }<div
            class={chartTooltip.tooltip}
            style:--pm-chart-tip-x={`${readout.tooltip?.x}px`}
            style:--pm-chart-tip-y={`${readout.tooltip?.y}px`}
            data-indicator={readout.tooltip?.indicator}
            data-side={readout.tooltip?.side}
            aria-hidden="true"
            >{#if readout.tooltip?.header !== undefined
              }<p class={chartTooltip.header}>{readout.tooltip?.header}</p
            >{/if
            }<ul class={chartTooltip.rows}
              >{#each readout.tooltip?.rows ?? [] as row (row.key)
                }<li class={chartTooltip.row}
                  ><span class={chartTooltip.key} style:--pm-chart-key={row.paint}></span
                  ><span class={chartTooltip.value}>{row.value}</span
                  ><span class={chartTooltip.label}>{row.label}</span
                ></li
              >{/each
            }</ul
          ></div
        >{/if
      }</div
      ><div class={chartFrame.xAxis}
        >{#if (model.axes?.x) !== undefined
          }<div class={chartAxis.axis} data-orientation="x" aria-hidden="true"
            >{#each (model.axes?.x) ?? [] as tick (tick.key)
              }<span class={chartAxis.tick} style:left={`${tick.at}px`} data-align={tick.align}
                >{tick.label
              }</span
            >{/each
          }</div
        >{/if
      }</div
    ></div
    >{#if model.legend
      }{#if model.painted.length > 0
        }<ul class={styles.legend} data-key-shape="rect"
          >{#each model.painted as entry (entry.key)
            }<li class={chartLegend.item}
              ><button
                class={chartLegend.key}
                type="button"
                aria-pressed={hidden.has(entry.key) ? 'false' : 'true'}
                onclick={() => { hidden = toggleSeries(hidden, entry.key) }}
                ><span
                  class={chartLegend.swatch}
                  style:--pm-chart-key={entry.paint}
                  aria-hidden="true"
                ></span
                >{#if entry.icon !== undefined
                  }<span class={chartLegend.glyph}><Icon name={entry.icon} size="sm" /></span
                >{/if
                }<span class={chartLegend.label}>{entry.label}</span
              ></button
            ></li
          >{/each
        }</ul
      >{/if
    }{/if
    }<span class={a11y.visuallyHidden}>{model.summary}</span
    ><div class={chartTwin.twin} data-state={twinOpen ? 'open' : 'closed'}
      ><div class={chartTwin.toggle}
        ><Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          iconOnly={true}
          label={twinOpen ? messages.hideTable(label) : messages.showTable(label)}
          onClick={() => { twinOpen = !twinOpen }}
      /></div
      >{#if twinOpen
        }<div class={chartTwin.table}
          ><Table label={messages.tableLabel(label)} caption={messages.tableLabel(label)}
            ><TableHead
              ><TableRow
                >{#each model.twin.columns as column (column.key)
                  }<TableHeader numeric={column.numeric}>{column.label}</TableHeader
                >{/each
              }</TableRow
            ></TableHead
            ><TableBody
              >{#each model.twin.rows as row, line (line)
                }<TableRow
                  >{#each row as cell, cellIndex (model.twin.columns[cellIndex]?.key ?? cellIndex)
                    }<TableCell numeric={model.twin.columns[cellIndex]?.numeric}
                      >{cell === '' ? '—' : cell
                    }</TableCell
                  >{/each
                }</TableRow
              >{/each
            }</TableBody
          ></Table
        ></div
      >{/if
    }</div
    ><span class={a11y.visuallyHidden}
      ><div aria-live="polite" aria-atomic="true">{readout.announcement}</div
    ></span
  ></figure
>{/if
}{@render joined.end?.()}
